mapper.select:
select cast(created_at as date) as event_day, entrypoint, result, count(*) as event_count from release_distribution_events where created_at >= #{windowStart}
and release_channel = #{releaseChannel}
group by cast(created_at as date), entrypoint, result order by event_day desc, entrypoint, result

with share_side as ( select count(*) as total_share_download_fallback_events, max(created_at) as share_last_seen_at from share_landing_events where created_at >= #{windowStart} and entrypoint = 'download' and result = 'download_fallback' ), release_side as ( select count(*) as total_release_share_card_events, max(created_at) as release_last_seen_at from release_distribution_events where created_at >= #{windowStart} and source = 'share_card'
and release_channel = #{releaseChannel}
) select total_share_download_fallback_events, share_last_seen_at, total_release_share_card_events, release_last_seen_at from share_side cross join release_side

with share_download as ( select cast(created_at as date) as event_day, coalesce(platform, 'unknown') as platform, count(*) as share_download_fallback_count from share_landing_events where created_at >= #{windowStart} and entrypoint = 'download' and result = 'download_fallback' group by cast(created_at as date), coalesce(platform, 'unknown') ), release_share_card as ( select cast(created_at as date) as event_day, coalesce(platform, 'unknown') as platform, count(*) as release_share_card_count from release_distribution_events where created_at >= #{windowStart} and source = 'share_card'
and release_channel = #{releaseChannel}
group by cast(created_at as date), coalesce(platform, 'unknown') ) select coalesce(sd.event_day, rd.event_day) as event_day, coalesce(sd.platform, rd.platform) as platform, coalesce(sd.share_download_fallback_count, 0) as share_download_fallback_count, coalesce(rd.release_share_card_count, 0) as release_share_card_count, coalesce(rd.release_share_card_count, 0) - coalesce(sd.share_download_fallback_count, 0) as release_minus_share from share_download sd full outer join release_share_card rd on sd.event_day = rd.event_day and sd.platform = rd.platform order by event_day desc, platform

with recent_release as ( select 'release_distribution' as surface, event_id as sort_id, created_at, release_channel as channel, source, entrypoint, coalesce(platform, 'unknown') as platform, result, failure_reason from release_distribution_events where created_at >= #{windowStart}
and release_channel = #{releaseChannel}
order by created_at desc, event_id desc limit #{limit} ), recent_share as ( select 'share_landing' as surface, event_id as sort_id, created_at, cast(null as varchar(32)) as channel, coalesce(source, 'unknown') as source, entrypoint, coalesce(platform, 'unknown') as platform, result, failure_reason from share_landing_events where created_at >= #{windowStart} order by created_at desc, event_id desc limit #{limit} ) select surface, created_at, channel, source, entrypoint, platform, result, failure_reason, sort_id from ( select * from recent_release union all select * from recent_share ) rows order by created_at desc, sort_id desc, surface limit #{limit}
